function validateReplyMessage(message) {
  for (const key of ["messageId", "threadId", "from"])
    if (typeof message?.[key] !== "string" || message[key].trim() === "")
      throw new Error("Incoming Gmail message is missing " + key + ".");
  if (
    typeof message.subject !== "string" ||
    typeof message.body !== "string" ||
    /[\r\n]/.test(message.from + message.subject)
  )
    throw new Error("Gmail subject, sender and body fields are invalid.");
  return {
    messageId: message.messageId,
    threadId: message.threadId,
    from: message.from,
    subject: message.subject,
    body: message.body,
  };
}

return $input.all().map((item, index) => {
  const source = item.json;
  const message = validateReplyMessage({
    messageId: source.id,
    threadId: source.threadId,
    from:
      (Array.isArray(source.from?.value)
        ? source.from.value.map((mailbox) => mailbox.address).join(",")
        : source.from?.text) ??
      source.headers?.from?.replace(/^From:\s*/i, "") ??
      source.from,
    subject: source.subject ?? source.headers?.subject ?? "",
    body:
      typeof source.html === "string" && source.html
        ? source.html
        : typeof source.textAsHtml === "string" && source.textAsHtml
          ? source.textAsHtml
          : (source.text ?? ""),
  });
  return { json: message, pairedItem: { item: index } };
});

function validateReplyDecision(completion) {
  if (
    !completion ||
    typeof completion !== "object" ||
    Array.isArray(completion) ||
    typeof completion.needsReply !== "boolean"
  )
    throw new Error("The assessment must contain a boolean needsReply.");
  return completion.needsReply;
}

const messages = $("Prepare Incoming Messages")
    .all()
    .map((item) => item.json),
  items = $input.all();
if (items.length !== messages.length)
  throw new Error("Reply decision count differs from messages.");
return items.map((item, index) => {
  let result = item.json;
  if (typeof result.text === "string") result = JSON.parse(result.text);
  if (result.output && typeof result.output === "object") result = result.output;
  return {
    json: { ...messages[index], needsReply: validateReplyDecision(result) },
    pairedItem: { item: index },
  };
});

function prepareReplyDraft(message, completion) {
  if (typeof completion !== "string" || completion.trim() === "")
    throw new Error("The reply model returned no draft text.");
  const escape = (text) =>
    text
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;")
      .replaceAll("'", "&#39;");
  return {
    sourceMessageId: message.messageId,
    threadId: message.threadId,
    to: message.from,
    subject: "Re: " + message.subject,
    body: escape(completion).replace(/\r\n|\r|\n/g, "<br />\n"),
  };
}

const messages = $("Validate All Reply Decisions")
    .all()
    .map((item) => item.json)
    .filter((message) => message.needsReply),
  items = $input.all();
if (items.length !== messages.length)
  throw new Error("Reply count differs from selected messages.");
return items.map((item, index) => ({
  json: prepareReplyDraft(messages[index], item.json.text),
  pairedItem: { item: index },
}));
